inputs = ['zb', 'bfy', 'ukci', 'wid', 'eweay']
outputs = ['zb', 'bfh', 'uckci', 'wivedud', 'eduweduah']

# Analyze each transformation
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Example {i}: '{inp}' -> '{outp}'")

    # Find differences
    if inp != outp:
        min_len = min(len(inp), len(outp))
        diff_pos = -1
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_pos = j
                break

        if diff_pos >= 0:
            print(f"  First difference at position {diff_pos}")
            print(f"  Input char: '{inp[diff_pos]}'")
            print(f"  Output char: '{outp[diff_pos]}'")

            # Check if it's insertion/deletion
            if len(inp) < len(outp):
                print(f"  Insertion detected at position {diff_pos}")
            elif len(inp) > len(outp):
                print(f"  Deletion detected at position {diff_pos}")
            else:
                print(f"  Substitution detected")
        else:
            # Check if it's length change
            if len(inp) < len(outp):
                print(f"  Insertion at end: {len(inp)} -> {len(outp)}")
            elif len(inp) > len(outp):
                print(f"  Deletion at end: {len(inp)} -> {len(outp)}")
            else:
                print("  No difference found")
    else:
        print("  No change")
    print()

