inputs = ['zb', 'bfy', 'ukci', 'wid', 'eweay']
outputs = ['zb', 'bfh', 'uckci', 'wivedud', 'eduweduah']

print("Detailed character-by-character comparison:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\n{i}: '{inp}' -> '{outp}'")
    print("Positions: ", end="")
    for j in range(max(len(inp), len(outp))):
        if j < len(inp) and j < len(outp):
            print(f"{j}({inp[j]}->{outp[j]}) ", end="")
        elif j < len(inp):
            print(f"{j}({inp[j]}->) ", end="")
        else:
            print(f"{j}(->{outp[j]}) ", end="")
    print()

